#!/bin/bash

#SBATCH -J er_u1_embed
#SBATCH --mail-user=mengjing@iu.edu
#SBATCH --mail-type=FAIL
#SBATCH -p h100-single
#SBATCH --gpus-per-node h100:1
#SBATCH -o logs/er_u1_embed_%A_%a.txt
#SBATCH -e logs/er_u1_embed_%A_%a.err
#SBATCH --nodes=1
#SBATCH --ntasks-per-node=1
#SBATCH --cpus-per-task=8
#SBATCH --time=8:00:00
#SBATCH --mem=32G
#SBATCH -A r00939

# Uni-Mol v1 embeddings (stage 2, GPU) for the Enamine REAL lead-like
# library, reusing the conformers ALREADY GENERATED by the sibling repo
# al-eval-framework (see its BILLION_SCALE_PIPELINE.md): 1000/1000 shards,
# 5.5 TB, zero failures. That is ~2,021 CPU-hours of RDKit ETKDG work this
# job does not have to repeat.
#
# Reuse is safe because both repos write byte-identical LMDB: _KEY_WIDTH=13
# zero-padded global-index keys and pickle.dumps({"atoms", "coordinates"})
# values, with shard files named chunk_XXXXX.lmdb -- exactly what
# compute_unimol_embeddings_chunk.py's --conformer-chunks-dir expects.
# Verified directly: chunk_00000.lmdb holds 1,559,854 entries, first key
# b'0000000000000', value a dict with those two fields.
#
# !! THIS JOB RUNS IN SOURCE ORDER, UNLIKE THE OTHER BACKBONES !!
# The conformers are keyed to the raw surA_smiles.txt (1,559,853,242 rows,
# duplicates included, sorted by docking score), so --smiles-file and
# --total-count MUST be the raw file's, not the deduplicated pool's --
# _chunk_bounds() must reproduce the boundaries stage 1 used or every
# molecule pairs with the wrong conformer (compute_unimol_embeddings_chunk.py
# re-derives expected atom counts from SMILES and fails loudly on mismatch,
# but do not rely on that as the only guard).
#
# So the output is 1,559,853,242 x 512 = 3.2 TB in SOURCE order, and a
# follow-up gather is required to bring it into the pool's deduplicated,
# shuffled order before use:
#     out[j] = source_embeddings[permutation[j]]   for j in 0..1,531,875,934
# using dedup/permutation.npy from submit_enamine_build_pool.sh -- the same
# convention shuffle_embeddings.py already applies to other backbones.
# That gather is I/O, not GPU, and drops the 27,977,307 duplicate rows.
#
# The alternative -- regenerating conformers against the deduplicated,
# shuffled pool (submit_enamine_unimol_conformers_bigred.sh, ~2,021 CPU-h)
# -- gives chunk-aligned output with no gather. Reuse is cheaper; that
# script exists if the alignment bookkeeping proves not worth it.
#
# Cost: 1.76 ms/mol measured on D4 (chunk 81: 1,417,528 molecules in
# 2,494.8 s) -> 763 GPU-h over 1,559,853,242 rows. At NUM_CHUNKS=1000 that
# is 1,559,854 molecules/chunk, ~46 min each, so --time=8:00:00 is ~10x the
# median chunk. Wall time ~12 h at %64 concurrency.
#
# NUM_CHUNKS MUST be 1000 to match stage 1. Passing anything else silently
# shifts chunk boundaries.
#
# Usage:
#   sbatch --array=0-999%64 slurm/embed/enamine1.56B/submit_enamine_unimol_embed_h100single.sh 1000

set -euo pipefail

NUM_CHUNKS="${1:?Usage: sbatch --array=0-999%64 $0 <NUM_CHUNKS>   (must be 1000)}"
OFFSET="${2:-0}"
TASK_ID=$(( ${SLURM_ARRAY_TASK_ID:?submit with --array=0-999} + OFFSET ))

if [ "$TASK_ID" -ge "$NUM_CHUNKS" ]; then
    echo "[skip] chunk-id $TASK_ID >= NUM_CHUNKS $NUM_CHUNKS -- nothing to do for this task"
    exit 0
fi

if [ -n "${SLURM_SUBMIT_DIR:-}" ]; then
    cd "$SLURM_SUBMIT_DIR"
else
    cd "$(git -C "$(dirname "${BASH_SOURCE[0]}")" rev-parse --show-toplevel)"
fi
set -a
[ -f config.env ] && source config.env
set +a
: "${CONDA_SH:=/N/slate/mengjing/miniconda3/etc/profile.d/conda.sh}"
: "${CONDA_ENV:=py310}"
source "$CONDA_SH"
conda activate "$CONDA_ENV"
mkdir -p logs

export OMP_NUM_THREADS="$SLURM_CPUS_PER_TASK"
export MKL_NUM_THREADS="$SLURM_CPUS_PER_TASK"
export OPENBLAS_NUM_THREADS="$SLURM_CPUS_PER_TASK"
export SRUN_CPUS_PER_TASK="$SLURM_CPUS_PER_TASK"

ER_ROOT="${ER_ROOT:-/N/project/SingleCell_Image/mengjing/enamine_real_1.56B}"
SMILES="$ER_ROOT/surA_smiles.txt"                 # raw, source order -- see above
TOTAL=1559853242                                  # raw row count, NOT the deduped 1,531,875,935
CONF_DIR="$ER_ROOT/_conformer_output/_unimol_cache_7d48f755fa/_chunks"

[ -d "$CONF_DIR" ] || { echo "[u1] ERROR: conformer shards not found at $CONF_DIR"; exit 1; }

mkdir -p "$ER_ROOT/_unimol_chunks"
lfs setstripe -c -1 "$ER_ROOT/_unimol_chunks" 2>/dev/null || true

echo "[u1] chunk $TASK_ID/$NUM_CHUNKS  total=$TOTAL (source order)  conformers=$CONF_DIR"

srun --cpu-bind=none python embed/compute/compute_unimol_embeddings_chunk.py \
    --smiles-file "$SMILES" --total-count "$TOTAL" \
    --conformer-chunks-dir "$CONF_DIR" \
    --chunk-id "$TASK_ID" --num-chunks "$NUM_CHUNKS" \
    --chunks-dir "$ER_ROOT/_unimol_chunks"
